async function block(root,name,size,pos,mat,r=0.08){const g=await roundedBoxGeo(...size,Math.min(...size)*r,{style:'chamfer'});return createPart(name,g,mat,{position:pos,parent:root});}
const meta={name:'battery-bank',role:'prop'};
async function build(){const root=createRoot('battery-bank'),m=styleMaterials();
await block(root,'plinth',[2.5,0.2,1.2],[0,0.1,0],m.panelGray,0.2);await block(root,'cabinet',[2.28,1.23,1.02],[0,0.815,0],m.panel,0.18);
for(const x of [-1.08,1.08])await block(root,'end armor',[0.23,1.29,1.1],[x,0.83,0],m.panelGray,0.25);
for(const x of [-0.67,0,0.67])await block(root,'orange access panel',[0.58,0.61,0.045],[x,0.68,0.52],m.accent,0.3);
await block(root,'charge surround',[1.45,0.26,0.05],[-0.2,1.26,0.535],m.trim,0.2);
const bar=new THREE.Group();bar.name='charge_bar';root.add(bar);for(let i=0;i<8;i++) await block(bar,'charge_segment_'+(i+1),[0.13+i*0.0001,0.13,0.025],[-0.78+i*0.165,1.26,0.57],m.glowWarm);
await block(root,'screen bezel',[0.28,0.25,0.05],[0.78,1.25,0.54],m.panelGray);await block(root,'screen',[0.2,0.15,0.02],[0.78,1.25,0.575],m.visor);
await block(root,'beacon base',[0.16,0.04,0.16],[0.68,1.45,0],m.panelGray);const anchor=new THREE.Group();anchor.name='info_anchor';anchor.position.set(0.68,1.51,0);root.add(anchor);await block(anchor,'beacon',[0.09,0.08,0.09],[0,0,0],m.glowCool);return root;}
